/**
 * Generador QR Offline ISO/IEC 18004 (Byte Mode, Versiones 1-14, Reed-Solomon GF(256))
 * Sin dependencias externas ni CDN.
 * Expone `window.QRCode.toCanvas(canvasEl, text, options, cb)` y `window.QRCode.toDataURL(text, options)`.
 */
(function (global) {
  'use strict';

  // Tablas GF(256) con polinomio primitivo 0x11d (285)
  const EXP_TABLE = new Uint8Array(512);
  const LOG_TABLE = new Uint8Array(256);
  (function initGaloisTables() {
    let x = 1;
    for (let i = 0; i < 255; i++) {
      EXP_TABLE[i] = x;
      LOG_TABLE[x] = i;
      x <<= 1;
      if (x & 0x100) {
        x ^= 0x11d;
      }
    }
    for (let i = 255; i < 512; i++) {
      EXP_TABLE[i] = EXP_TABLE[i - 255];
    }
  })();

  function gfMul(a, b) {
    if (a === 0 || b === 0) return 0;
    return EXP_TABLE[LOG_TABLE[a] + LOG_TABLE[b]];
  }

  function rsGeneratorPoly(degree) {
    let poly = new Uint8Array([1]);
    for (let i = 0; i < degree; i++) {
      const next = new Uint8Array(poly.length + 1);
      const root = EXP_TABLE[i];
      for (let j = 0; j < poly.length; j++) {
        next[j] ^= poly[j];
        next[j + 1] ^= gfMul(poly[j], root);
      }
      poly = next;
    }
    return poly;
  }

  function rsComputeRemainder(data, ecLen) {
    const gen = rsGeneratorPoly(ecLen);
    const rem = new Uint8Array(ecLen);
    for (let i = 0; i < data.length; i++) {
      const factor = data[i] ^ rem[0];
      rem.copyWithin(0, 1);
      rem[ecLen - 1] = 0;
      if (factor !== 0) {
        for (let j = 0; j < ecLen; j++) {
          rem[j] ^= gfMul(gen[j + 1], factor);
        }
      }
    }
    return rem;
  }

  // Parámetros de versión 1 a 14 para Nivel de Corrección L (01) y M (00)
  // [totalCodewords, ecCodewordsPerBlock, numBlocksGroup1, dataCwGroup1, numBlocksGroup2, dataCwGroup2]
  const VERSION_PARAMS_L = [
    null,
    [26, 7, 1, 19, 0, 0],     // v1
    [44, 10, 1, 34, 0, 0],    // v2
    [70, 15, 1, 55, 0, 0],    // v3
    [100, 20, 1, 80, 0, 0],   // v4
    [134, 26, 1, 108, 0, 0],  // v5
    [172, 18, 2, 68, 0, 0],   // v6
    [196, 20, 2, 78, 0, 0],   // v7
    [242, 24, 2, 97, 0, 0],   // v8
    [292, 30, 2, 116, 0, 0],  // v9
    [346, 18, 2, 68, 2, 69],  // v10
    [404, 20, 4, 81, 0, 0],   // v11
    [466, 24, 2, 92, 2, 93],  // v12
    [532, 26, 4, 107, 0, 0],  // v13
    [581, 30, 3, 115, 1, 116] // v14
  ];

  const VERSION_PARAMS_M = [
    null,
    [26, 10, 1, 16, 0, 0],    // v1
    [44, 16, 1, 28, 0, 0],    // v2
    [70, 26, 1, 44, 0, 0],    // v3
    [100, 18, 2, 32, 0, 0],   // v4
    [134, 24, 2, 43, 0, 0],   // v5
    [172, 16, 4, 27, 0, 0],   // v6
    [196, 18, 4, 31, 0, 0],   // v7
    [242, 22, 2, 38, 2, 39],  // v8
    [292, 22, 3, 36, 2, 37],  // v9
    [346, 26, 4, 43, 1, 44],  // v10
    [404, 30, 1, 50, 4, 51],  // v11
    [466, 22, 6, 36, 2, 37],  // v12
    [532, 22, 8, 37, 1, 38],  // v13
    [581, 24, 4, 40, 5, 41]   // v14
  ];

  const ALIGNMENT_PATTERNS = [
    null,
    [],
    [6, 18],
    [6, 22],
    [6, 26],
    [6, 30],
    [6, 34],
    [6, 22, 38],
    [6, 24, 42],
    [6, 26, 46],
    [6, 28, 50],
    [6, 30, 54],
    [6, 32, 58],
    [6, 34, 62],
    [6, 26, 46, 66]
  ];

  function utf8Bytes(str) {
    return new TextEncoder().encode(String(str));
  }

  function selectVersion(byteLength, ecLevel) {
    const table = ecLevel === 'L' ? VERSION_PARAMS_L : VERSION_PARAMS_M;
    for (let v = 1; v < table.length; v++) {
      const p = table[v];
      const totalDataCw = p[2] * p[3] + p[4] * p[5];
      const lenBits = v <= 9 ? 8 : 16;
      const maxBytes = Math.floor((totalDataCw * 8 - 4 - lenBits) / 8);
      if (byteLength <= maxBytes) {
        return { version: v, params: p, totalDataCw };
      }
    }
    throw new Error('Texto demasiado largo para generar código QR (máx ~450 bytes).');
  }

  function buildDataCodewords(bytes, version, totalDataCw) {
    const bits = [];
    const pushBits = (val, len) => {
      for (let i = len - 1; i >= 0; i--) {
        bits.push((val >>> i) & 1);
      }
    };

    // Modo Byte = 0100 (4)
    pushBits(0b0100, 4);
    pushBits(bytes.length, version <= 9 ? 8 : 16);
    for (let i = 0; i < bytes.length; i++) {
      pushBits(bytes[i], 8);
    }

    const maxBits = totalDataCw * 8;
    const terminator = Math.min(4, maxBits - bits.length);
    pushBits(0, terminator);

    while (bits.length % 8 !== 0) {
      bits.push(0);
    }

    const codewords = new Uint8Array(totalDataCw);
    for (let i = 0; i < bits.length / 8; i++) {
      let b = 0;
      for (let j = 0; j < 8; j++) {
        b = (b << 1) | bits[i * 8 + j];
      }
      codewords[i] = b;
    }

    const padBytes = [0xec, 0x11];
    let padIdx = 0;
    for (let i = bits.length / 8; i < totalDataCw; i++) {
      codewords[i] = padBytes[padIdx % 2];
      padIdx++;
    }

    return codewords;
  }

  function interleaveBlocks(dataCw, params) {
    const [, ecCwPerBlock, g1Blocks, g1DataCw, g2Blocks, g2DataCw] = params;
    const dataBlocks = [];
    const ecBlocks = [];
    let offset = 0;

    for (let i = 0; i < g1Blocks; i++) {
      const block = dataCw.subarray(offset, offset + g1DataCw);
      offset += g1DataCw;
      dataBlocks.push(block);
      ecBlocks.push(rsComputeRemainder(block, ecCwPerBlock));
    }
    for (let i = 0; i < g2Blocks; i++) {
      const block = dataCw.subarray(offset, offset + g2DataCw);
      offset += g2DataCw;
      dataBlocks.push(block);
      ecBlocks.push(rsComputeRemainder(block, ecCwPerBlock));
    }

    const result = [];
    const maxDataLen = Math.max(g1DataCw, g2DataCw);
    for (let col = 0; col < maxDataLen; col++) {
      for (let b = 0; b < dataBlocks.length; b++) {
        if (col < dataBlocks[b].length) {
          result.push(dataBlocks[b][col]);
        }
      }
    }
    for (let col = 0; col < ecCwPerBlock; col++) {
      for (let b = 0; b < ecBlocks.length; b++) {
        result.push(ecBlocks[b][col]);
      }
    }

    return new Uint8Array(result);
  }

  function createMatrix(version) {
    const size = version * 4 + 17;
    const modules = Array.from({ length: size }, () => new Uint8Array(size));
    const isFunction = Array.from({ length: size }, () => new Uint8Array(size));

    const setFunctionModule = (r, c, dark) => {
      if (r < 0 || r >= size || c < 0 || c >= size) return;
      modules[r][c] = dark ? 1 : 0;
      isFunction[r][c] = 1;
    };

    const drawFinderPattern = (top, left) => {
      for (let dr = -1; dr <= 7; dr++) {
        for (let dc = -1; dc <= 7; dc++) {
          const r = top + dr;
          const c = left + dc;
          if (r < 0 || r >= size || c < 0 || c >= size) continue;
          const inOuter = dr >= 0 && dr <= 6 && dc >= 0 && dc <= 6;
          const inWhiteRing = dr >= 1 && dr <= 5 && dc >= 1 && dc <= 5;
          const inCenter = dr >= 2 && dr <= 4 && dc >= 2 && dc <= 4;
          const dark = inOuter && (!inWhiteRing || inCenter);
          setFunctionModule(r, c, dark);
        }
      }
    };

    drawFinderPattern(0, 0);
    drawFinderPattern(0, size - 7);
    drawFinderPattern(size - 7, 0);

    // Timing patterns
    for (let i = 8; i < size - 8; i++) {
      setFunctionModule(6, i, i % 2 === 0);
      setFunctionModule(i, 6, i % 2 === 0);
    }

    // Alignment patterns
    const coords = ALIGNMENT_PATTERNS[version] || [];
    for (let i = 0; i < coords.length; i++) {
      for (let j = 0; j < coords.length; j++) {
        if (
          (i === 0 && j === 0) ||
          (i === 0 && j === coords.length - 1) ||
          (i === coords.length - 1 && j === 0)
        ) {
          continue;
        }
        const cr = coords[i];
        const cc = coords[j];
        for (let dr = -2; dr <= 2; dr++) {
          for (let dc = -2; dc <= 2; dc++) {
            const dist = Math.max(Math.abs(dr), Math.abs(dc));
            setFunctionModule(cr + dr, cc + dc, dist !== 1);
          }
        }
      }
    }

    // Dark module
    setFunctionModule(4 * version + 9, 8, true);

    // Reservar áreas de formato
    for (let i = 0; i <= 8; i++) {
      if (!isFunction[8][i]) setFunctionModule(8, i, false);
      if (!isFunction[i][8]) setFunctionModule(i, 8, false);
    }
    for (let i = 0; i < 8; i++) {
      if (!isFunction[8][size - 1 - i]) setFunctionModule(8, size - 1 - i, false);
      if (!isFunction[size - 1 - i][8]) setFunctionModule(size - 1 - i, 8, false);
    }

    // Información de versión (para version >= 7)
    if (version >= 7) {
      let rem = version;
      for (let i = 0; i < 12; i++) {
        rem = (rem << 1) ^ ((rem >>> 11) * 0x1f25);
      }
      const vBits = (version << 12) | rem;
      for (let i = 0; i < 18; i++) {
        const bit = ((vBits >>> i) & 1) !== 0;
        const a = size - 11 + (i % 3);
        const b = Math.floor(i / 3);
        setFunctionModule(a, b, bit);
        setFunctionModule(b, a, bit);
      }
    }

    return { size, modules, isFunction };
  }

  function placeDataBits(matrix, codewords) {
    const { size, modules, isFunction } = matrix;
    let bitIdx = 0;
    const totalBits = codewords.length * 8;

    let upward = true;
    for (let right = size - 1; right >= 1; right -= 2) {
      if (right === 6) right = 5;
      for (let vert = 0; vert < size; vert++) {
        const r = upward ? size - 1 - vert : vert;
        for (let j = 0; j < 2; j++) {
          const c = right - j;
          if (!isFunction[r][c]) {
            let dark = false;
            if (bitIdx < totalBits) {
              const byteVal = codewords[bitIdx >>> 3];
              dark = ((byteVal >>> (7 - (bitIdx & 7))) & 1) !== 0;
              bitIdx++;
            }
            modules[r][c] = dark ? 1 : 0;
          }
        }
      }
      upward = !upward;
    }
  }

  function applyMaskAndFormat(matrix, maskIndex, ecLevel) {
    const { size, modules, isFunction } = matrix;
    const out = Array.from({ length: size }, (_, r) => Uint8Array.from(modules[r]));

    const maskFn = (r, c) => {
      switch (maskIndex) {
        case 0: return (r + c) % 2 === 0;
        case 1: return r % 2 === 0;
        case 2: return c % 3 === 0;
        case 3: return (r + c) % 3 === 0;
        case 4: return (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0;
        case 5: return ((r * c) % 2) + ((r * c) % 3) === 0;
        case 6: return (((r * c) % 2) + ((r * c) % 3)) % 2 === 0;
        case 7: return (((r + c) % 2) + ((r * c) % 3)) % 2 === 0;
        default: return false;
      }
    };

    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        if (!isFunction[r][c] && maskFn(r, c)) {
          out[r][c] ^= 1;
        }
      }
    }

    // Format bits: L = 01 (1), M = 00 (0)
    const ecFormatBits = ecLevel === 'L' ? 1 : 0;
    const data = (ecFormatBits << 3) | maskIndex;
    let rem = data;
    for (let i = 0; i < 10; i++) {
      rem = (rem << 1) ^ ((rem >>> 9) * 0x537);
    }
    const formatBits = ((data << 10) | rem) ^ 0x5412;

    const getBit = (idx) => ((formatBits >>> idx) & 1);

    // Top-left
    for (let i = 0; i <= 5; i++) out[8][i] = getBit(i);
    out[8][7] = getBit(6);
    out[8][8] = getBit(7);
    out[7][8] = getBit(8);
    for (let i = 9; i < 15; i++) out[14 - i][8] = getBit(i);

    // Top-right & Bottom-left
    for (let i = 0; i < 8; i++) out[8][size - 1 - i] = getBit(i);
    for (let i = 8; i < 15; i++) out[size - 15 + i][8] = getBit(i);
    out[size - 8][8] = 1;

    return out;
  }

  function computePenalty(grid) {
    const size = grid.length;
    let penalty = 0;

    // Regla 1: filas y columnas con >=5 módulos iguales consecutivos
    for (let r = 0; r < size; r++) {
      let runColor = grid[r][0];
      let runLen = 1;
      for (let c = 1; c < size; c++) {
        if (grid[r][c] === runColor) {
          runLen++;
          if (runLen === 5) penalty += 3;
          else if (runLen > 5) penalty += 1;
        } else {
          runColor = grid[r][c];
          runLen = 1;
        }
      }
    }
    for (let c = 0; c < size; c++) {
      let runColor = grid[0][c];
      let runLen = 1;
      for (let r = 1; r < size; r++) {
        if (grid[r][c] === runColor) {
          runLen++;
          if (runLen === 5) penalty += 3;
          else if (runLen > 5) penalty += 1;
        } else {
          runColor = grid[r][c];
          runLen = 1;
        }
      }
    }

    // Regla 2: bloques 2x2
    for (let r = 0; r < size - 1; r++) {
      for (let c = 0; c < size - 1; c++) {
        const v = grid[r][c];
        if (v === grid[r][c + 1] && v === grid[r + 1][c] && v === grid[r + 1][c + 1]) {
          penalty += 3;
        }
      }
    }

    return penalty;
  }

  function encodeQRMatrix(text, ecLevel = 'M') {
    const level = ecLevel === 'L' ? 'L' : 'M';
    const bytes = utf8Bytes(text);
    const { version, params, totalDataCw } = selectVersion(bytes.length, level);
    const dataCw = buildDataCodewords(bytes, version, totalDataCw);
    const fullCw = interleaveBlocks(dataCw, params);
    const matrix = createMatrix(version);
    placeDataBits(matrix, fullCw);

    let bestGrid = null;
    let bestPenalty = Infinity;
    for (let mask = 0; mask < 8; mask++) {
      const candidate = applyMaskAndFormat(matrix, mask, level);
      const score = computePenalty(candidate);
      if (score < bestPenalty) {
        bestPenalty = score;
        bestGrid = candidate;
      }
    }

    return bestGrid;
  }

  function toCanvas(canvas, text, options, callback) {
    let opts = options || {};
    let cb = callback;
    if (typeof options === 'function') {
      cb = options;
      opts = {};
    }

    try {
      if (!canvas || typeof canvas.getContext !== 'function') {
        throw new Error('Elemento <canvas> inválido para renderizar QR.');
      }
      if (!text || !String(text).trim()) {
        throw new Error('La URL o texto del código QR está vacío.');
      }

      const ecLevel = (opts.errorCorrectionLevel || 'M').toUpperCase();
      const grid = encodeQRMatrix(String(text), ecLevel);
      const moduleCount = grid.length;
      const margin = typeof opts.margin === 'number' ? opts.margin : 2;
      const totalModules = moduleCount + margin * 2;

      const targetSize = Number(opts.width) || Number(canvas.width) || 180;
      canvas.width = targetSize;
      canvas.height = targetSize;

      const ctx = canvas.getContext('2d');
      ctx.imageSmoothingEnabled = false;

      const lightColor = (opts.color && opts.color.light) || '#ffffff';
      const darkColor = (opts.color && opts.color.dark) || '#0f172a';

      ctx.fillStyle = lightColor;
      ctx.fillRect(0, 0, targetSize, targetSize);

      const scale = targetSize / totalModules;
      ctx.fillStyle = darkColor;

      for (let r = 0; r < moduleCount; r++) {
        for (let c = 0; c < moduleCount; c++) {
          if (grid[r][c]) {
            const x0 = Math.floor((c + margin) * scale);
            const y0 = Math.floor((r + margin) * scale);
            const x1 = Math.ceil((c + margin + 1) * scale);
            const y1 = Math.ceil((r + margin + 1) * scale);
            ctx.fillRect(x0, y0, Math.max(1, x1 - x0), Math.max(1, y1 - y0));
          }
        }
      }

      if (typeof cb === 'function') cb(null, canvas);
      return Promise.resolve(canvas);
    } catch (err) {
      console.error('[QRCode.toCanvas] Error generando QR:', err);
      if (typeof cb === 'function') cb(err);
      return Promise.reject(err);
    }
  }

  function toDataURL(text, options, callback) {
    const tempCanvas = document.createElement('canvas');
    return toCanvas(tempCanvas, text, options).then(() => {
      const dataUrl = tempCanvas.toDataURL('image/png');
      if (typeof callback === 'function') callback(null, dataUrl);
      return dataUrl;
    });
  }

  const QRCodeAPI = {
    toCanvas,
    toDataURL,
    encodeQRMatrix
  };

  global.QRCode = QRCodeAPI;
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = QRCodeAPI;
  }
})(typeof window !== 'undefined' ? window : globalThis);
